"""Brute-force reference for plan mode (small instances only)."""
import itertools, json, sys, subprocess
sys.path.insert(0, '/workspace/submission')
import importlib.util
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)


def brute(req):
    R = m.parse_request(req)
    caps = R['caps']; F = R['flows']
    ben = {fid: m.flow_benefit(F[fid], R['runs'][fid], R['warmup']) for fid in F}
    pinned = R['pinned']
    ids = sorted(F)
    # feasibility of pinned
    used = {}
    for fid in pinned:
        for n in F[fid]['path']:
            used[n] = used.get(n, 0) + 1
    for n, c in used.items():
        if c > caps[n]:
            return {'infeasible': True}
    best = None
    for r in range(len(ids) + 1):
        for comb in itertools.combinations(ids, r):
            S = set(comb)
            if not set(pinned) <= S:
                continue
            u = {}
            ok = True
            for fid in comb:
                for n in F[fid]['path']:
                    u[n] = u.get(n, 0) + 1
                    if u[n] > caps[n]:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue
            v = sum(ben[fid] for fid in comb)
            key = (v, -len(comb))
            if best is None or key > best[0]:
                best = (key, sorted(comb), v)
    if best is None:
        return {'selected': [], 'saved': 0}
    return {'selected': best[1], 'saved': best[2]}
