import random, json, itertools, sys, subprocess
sys.path.insert(0,'/workspace/dev')
from brute_plan import brute

LETTERS = 'abcdefghijklmnopqrstuvwxyz'

def gen_case(rng, nflows=None, nnodes=None, tight=True):
    nflows = nflows if nflows is not None else rng.randint(1, 8)
    nnodes = nnodes if nnodes is not None else rng.randint(1, 6)
    nodes = ['n%d' % i for i in range(nnodes)]
    caps = {}
    for n in nodes:
        caps[n] = rng.choice([0,1,1,2,2,3,4,rng.randint(0,5)]) if tight else rng.randint(0,8)
    flows = []
    for i in range(nflows):
        k = rng.randint(2, min(5, nnodes))
        path = rng.sample(nodes, k)
        H = rng.randint(8, 20)
        kinds = []
        kinds.append('Q'); kinds.append('T')
        nd = rng.randint(0, max(0, H-5))
        kinds += ['D']*nd
        nk = H - len(kinds)
        kinds += ['K']*nk
        if nk < 1 or 4+nd >= H:
            return None
        kinds = rng.sample(kinds, H)
        tmpl = ''.join('%02x' % rng.randint(0,255) for _ in range(H))
        flows.append(dict(id='f%d'%i, path=path, template=tmpl, kinds=''.join(kinds)))
    warmup = rng.choice([0,0,1,2,3,rng.randint(0,10)])
    ids = [f['id'] for f in flows]
    pinned = rng.sample(ids, rng.randint(0, min(3, len(ids))))
    offers = {}
    for f in flows:
        r = rng.randint(0, 4)
        H = len(f['template'])//2
        runs = []
        tot = 0
        for _ in range(r):
            hdr = bytearray(rng.randint(0,255) for _ in range(H))
            # sometimes make it match
            kinds = f['kinds']; tmpl = bytes.fromhex(f['template'])
            if rng.random() < 0.7:
                for i,c in enumerate(kinds):
                    if c=='K': hdr[i]=tmpl[i]
                hdr[kinds.index('Q')] = rng.randint(0,7) if rng.random()<0.8 else rng.randint(8,255)
                hdr[kinds.index('T')] = rng.randint(1,255) if rng.random()<0.7 else rng.randint(0,len(f['path']))
            runs.append(dict(header=hdr.hex(), count=rng.randint(1, 50)))
        offers[f['id']] = runs
    return dict(mode='plan', caps=caps, flows=flows, warmup=warmup, pinned=pinned, offers=offers)

def main():
    rng = random.Random(7)
    bad = 0
    for t in range(3000):
        req = gen_case(rng, nflows=rng.choice([1,2,3,5,7,9,11]))
        if req is None: continue
        exp = brute(req)
        got = json.loads(subprocess.run(['python3','-I','-B','/workspace/submission/main.py'],
                input=json.dumps(req)+'\n',capture_output=True,text=True).stdout.strip())
        if exp != got:
            # check whether got is also optimal (secondary objective must match)
            if exp.get('infeasible') or got.get('infeasible'):
                print('INFEAS MISMATCH', json.dumps(req)); bad+=1
            else:
                # recompute value of got
                import brute_plan as bp
                R = bp.m.parse_request(req)
                ben = {fid: bp.m.flow_benefit(R['flows'][fid], R['runs'][fid], R['warmup']) for fid in R['flows']}
                v = sum(ben[x] for x in got['selected'])
                if v != exp['saved'] or len(got['selected']) != len(exp['selected']) or got['saved'] != v:
                    print('SUBOPT', json.dumps(req), 'exp', exp, 'got', got); bad+=1
                    if bad>3: break
        # verify saved recomputation & feasibility
        if 'selected' in got:
            R = None
    print('done, mismatches:', bad)
main()
